/bin/bash -lc "/usr/bin/python3 -B - <<'PY'
from pathlib import Path
import json,time,hashlib
r=Path.cwd();data=(r/'acceptance/checks/response.json').read_bytes()
for name in ('independent-result.json','attempt-1-independent.json'):(r/'results'/name).write_bytes(data)
(r/'review/acceptance.json').write_bytes(data);(r/'review/candidate.patch').write_bytes((r/'results/implementation.patch').read_bytes())
for name in ('load.py','transform.py'):(r/'review/candidate/src'/name).write_bytes((r/'implementer/src'/name).read_bytes())
checks={p.name:json.loads(p.read_text()) for p in (r/'implementer/checks').glob('*.json') if p.name"'!='"'request.json'}
(r/'review/development-checks.json').write_text(json.dumps({'handoff':json.loads((r/'implementer/handoff/implementation.json').read_text()),'checks':checks},indent=2)+'\\n')
hashes={str(p.relative_to(r/'review')):hashlib.sha256(p.read_bytes()).hexdigest() for p in (r/'review').rglob('*') if p.is_file() and not any(x.startswith('.') for x in p.relative_to(r/'review').parts)}
candidate={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for base in ('implementer','acceptance') for p in [r/base/'src/load.py',r/base/'src/transform.py',r/base/'tests/test_igdb_reliability.py']}
record=json.dumps({'bundle':hashes,'candidate':candidate},indent=2)+'\\n'
for name in ('pre-review-hashes.json','attempt-1-pre-review-hashes.json'):(r/'results'/name).write_text(record)
s=json.loads((r/'results/orchestrator.json').read_text());s['attempts'][1].update(acceptance_end=time.time(),acceptance_exit_code=json.loads(data)['exit_code'],result='attempt-1-independent.json');s['failures'].append({'phase':'independent','attempt':1,'failed':2,'passed':67,'classification':'same two frozen harness errors identified by initial review'});s['roles']['reviewer'].setdefault('followups',[]).append({'attempt':1,'start':time.time()});(r/'results/orchestrator.json').write_text(json.dumps(s,indent=2)+'\\n')
PY"

